/*
  # Catalogue OpenRouter reel

  Les quatre entrees precedentes portaient des noms inventes — « Recrue »,
  « Tacticienne », « Strategiste », « Maitresse » — et des identifiants ecrits
  de memoire. L'un d'eux, `anthropic/claude-3.5-haiku`, n'existe meme plus chez
  OpenRouter : un agent l'ayant choisi aurait echoue a chaque appel.

  Le catalogue est desormais celui d'OpenRouter, dans son integralite :
  **395 modeles**, avec leurs identifiants, leurs noms officiels, leurs
  tarifs reels et leur fenetre de contexte. Les modeles gratuits et ceux en
  essai (avec date d'expiration) y figurent.

  ## Identifiant
  `slug` porte directement l'identifiant OpenRouter. L'ancienne indirection
  entre un slug maison et un `provider_model` n'apportait rien et permettait
  aux deux de diverger.

  ## Fraicheur
  Les tarifs changent. La fonction Edge `sync-models` reimporte le catalogue et
  une tache quotidienne l'appelle : ce fichier n'est qu'un point de depart,
  fige au 2026-08-31.
*/

-- ---------------------------------------------------------------------------
-- 1. Structure alignee sur les champs d'OpenRouter
-- ---------------------------------------------------------------------------

ALTER TABLE llm_models
  ADD COLUMN IF NOT EXISTS provider       text NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS context_length integer NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS is_free        boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS expires_at     date,
  ADD COLUMN IF NOT EXISTS synced_at      timestamptz NOT NULL DEFAULT now();

-- `blurb` accueille desormais la description d'OpenRouter, plus longue.
ALTER TABLE llm_models ALTER COLUMN blurb DROP NOT NULL;
ALTER TABLE llm_models ALTER COLUMN provider_model DROP NOT NULL;

/*
  `tier` etait un classement maison. Le palier gratuit se lit maintenant sur
  `is_free`, et le reste se compare au prix : on garde la colonne pour ne pas
  casser d'anciennes requetes, sans plus s'y fier.
*/
ALTER TABLE llm_models ALTER COLUMN tier SET DEFAULT 'standard';

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'llm_models_tier_check') THEN
    ALTER TABLE llm_models DROP CONSTRAINT llm_models_tier_check;
  END IF;
END $$;

