  ('~deepseek/deepseek-v4-flash-latest', 'DeepSeek V4 Flash Latest', '~deepseek', 0.03, 0.16, 1310720, false, NULL, 'This model always redirects to the latest model in the DeepSeek V4 Flash family.'),
  ('~google/gemini-flash-latest', 'Google Gemini Flash Latest', '~google', 0.75, 3.75, 1048576, false, NULL, 'This model always redirects to the latest model in the Google Gemini Flash family.'),
  ('~google/gemini-pro-latest', 'Google Gemini Pro Latest', '~google', 2.0, 12.0, 1048576, false, NULL, 'This model always redirects to the latest model in the Google Gemini Pro family.'),
  ('~moonshotai/kimi-latest', 'MoonshotAI Kimi Latest', '~moonshotai', 2.55, 12.75, 1048576, false, NULL, 'This model always redirects to the latest model in the MoonshotAI Kimi family.'),
  ('~openai/gpt-latest', 'OpenAI GPT Latest', '~openai', 2.0, 10.0, 1050000, false, NULL, 'This model always redirects to the latest model in the OpenAI GPT family.'),
