ON CONFLICT (slug) DO UPDATE SET
  label              = EXCLUDED.label,
  provider           = EXCLUDED.provider,
  price_in_per_mtok  = EXCLUDED.price_in_per_mtok,
  price_out_per_mtok = EXCLUDED.price_out_per_mtok,
  context_length     = EXCLUDED.context_length,
  is_free            = EXCLUDED.is_free,
  expires_at         = EXCLUDED.expires_at,
  blurb              = EXCLUDED.blurb,
  enabled            = true,
  synced_at          = now();

UPDATE llm_models SET provider_model = slug WHERE provider_model IS DISTINCT FROM slug;

-- ---------------------------------------------------------------------------
-- 3. Reprise des anciens identifiants maison
-- ---------------------------------------------------------------------------

/*
  Les agents deja configures pointent vers « gratuit », « rapide », « solide »
  ou « elite ». On les rattache a un modele reel avant de supprimer ces
  entrees, sinon la cle etrangere sauterait.
*/
DO $$
DECLARE
  v_free text;
BEGIN
  SELECT slug INTO v_free
  FROM llm_models
  WHERE is_free AND enabled AND (expires_at IS NULL OR expires_at > now()::date)
  ORDER BY context_length DESC, slug
  LIMIT 1;

  UPDATE agent_configs SET model_slug = COALESCE(v_free, 'openai/gpt-4o-mini')
  WHERE model_slug = 'gratuit';
  UPDATE agents SET model_slug = COALESCE(v_free, 'openai/gpt-4o-mini')
  WHERE model_slug = 'gratuit';

  UPDATE agent_configs SET model_slug = 'openai/gpt-4o-mini' WHERE model_slug = 'rapide';
  UPDATE agents        SET model_slug = 'openai/gpt-4o-mini' WHERE model_slug = 'rapide';
  UPDATE agent_configs SET model_slug = 'openai/gpt-4o'      WHERE model_slug IN ('solide', 'elite');
  UPDATE agents        SET model_slug = 'openai/gpt-4o'      WHERE model_slug IN ('solide', 'elite');

  DELETE FROM llm_models WHERE slug IN ('gratuit', 'rapide', 'solide', 'elite');
END $$;

ALTER TABLE agent_configs ALTER COLUMN model_slug SET DEFAULT 'openai/gpt-4o-mini';
ALTER TABLE agents        ALTER COLUMN model_slug SET DEFAULT 'openai/gpt-4o-mini';

CREATE INDEX IF NOT EXISTS idx_models_provider ON llm_models (provider, label);
CREATE INDEX IF NOT EXISTS idx_models_free ON llm_models (is_free) WHERE enabled;
